steps.action:
curl -s -X POST "https://slack.com/api/conversations.list" \
  -H "Authorization: Bearer <TOKEN>" \
  -H "Content-Type: application/json" \
  -d '{"token": "<TOKEN>", "types": "public_channel", "limit": 1000}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'release' in ch['name'].lower():
            print(ch['id'], ch['name'])
else:
    print(data)
"

curl -s -X POST "https://slack.com/api/conversations.history" \
  -H "Authorization: Bearer <TOKEN>" \
  -H "Content-Type: application/json" \
  -d '{"token": "<TOKEN>", "channel": "C_REL", "limit": 100}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        if 'release cut is ready' in msg.get('text', '').lower():
            print(json.dumps(msg, indent=2))
else:
    print(json.dumps(data, indent=2))
"

